# Cycles of length 5
count5 = 0
for a in range(n):
    for b in range(n):
        if b == a: continue
        for c in range(n):
            if c in (a, b): continue
            for d in range(n):
                if d in (a, b, c): continue
                for e in range(n):
                    if e in (a, b, c, d): continue
                    if a < e or (a == e):  # canonical: smallest endpoint first
                        # cycle a-b-c-d-e-a
                        # To avoid duplicates, fix a as minimum and b < e (direction)
                        if a == min(a,b,c,d,e) and b < e:
                            cnf.append([-edge_var(a,b), -edge_var(b,c), -edge_var(c,d), 
                                       -edge_var(d,e), -edge_var(a,e)])
                            count5 += 1
print(f"  Length-5 cycles: {count5} clauses")
print(f"Total clauses so far: {len(cnf.clauses)}")
